"""Base module for ncclient and netconf_client wrappers"""
from __future__ import annotations

from abc import ABC, abstractmethod
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from netconf_client.ncclient import Manager as NetconfClientManager
    from ncclient import manager as NcclientManager


class LibrariesBase(ABC):
    """Abstract class for libraries: ncclient and netconf_client"""

    def __init__(self, manager: NetconfClientManager | NcclientManager):
        self.manager = manager

    @abstractmethod
    def get_without_filter(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def edit_config(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def get_xpath(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def get_subtree(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def get_session_id(self, *args, **kwargs) -> int:
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def create_subscription(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def take_notification(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def get_config(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def server_capabilities(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def client_capabilities(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def send_rpc(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError

    @abstractmethod
    def kill_session(self, *args, **kwargs):
        """abstract method"""
        raise NotImplementedError
